    'hero.sub': 'Enterprise Architecture &amp; IT Leadership',
    'hero.tagline': '<strong>When an extra perspective helps</strong>',
    'hero.desc': 'Senior architecture &amp; leadership experience in enterprise IT — driven to achieve innovation, structure, consistency, and team spirit.',
    'hero.btn.services': 'View Services',
